        public static int Pick(string key, bool large, int variant)
        {
            int[] ids;
            if (string.IsNullOrEmpty(key) || !(large ? Large : Small).TryGetValue(key, out ids) || ids.Length == 0)
                return 0;
            return ids[(variant & 0x7fffffff) % ids.Length];
        }
